import { forwardRef, useId } from 'react';

import { cn } from '../../../../utils/ui/cn';
import { useRakitConfig, getComponentIdentifier } from '../../../../config/RakitContext';

import type { RadioProps } from '../../../../types/ui/field/radio.types';
import type { FieldSize } from '../../../../types/ui/field/fieldWrapper.types';

export const Radio = forwardRef<HTMLInputElement, RadioProps>(
  (
    {
      id: customId,
      value,
      checked = false,
      onChange,
      label,
      description,
      disabled = false,
      size = 'md',
      variant = 'default',
      className,
      wrapperClassName,
      ...props
    },
    ref
  ) => {
    const config = useRakitConfig();
    const generatedId = useId();
    const inputId = customId || generatedId;
    const identifier = getComponentIdentifier('radio', config, inputId);

    const circleSizeClasses: Record<FieldSize, string> = {
      xs: 'w-3.5 h-3.5',
      sm: 'w-4 h-4',
      md: 'w-5 h-5',
      lg: 'w-6 h-6',
      xl: 'w-7 h-7',
    };

    const innerDotClasses: Record<FieldSize, string> = {
      xs: 'w-1 h-1',
      sm: 'w-1.5 h-1.5',
      md: 'w-2 h-2',
      lg: 'w-2.5 h-2.5',
      xl: 'w-3 h-3',
    };

    const isCard = variant === 'card';

    return (
      <label
        htmlFor={inputId}
        className={cn(
          'rakit-radio-wrapper relative flex items-start gap-3 select-none transition-all cursor-pointer',
          isCard &&
            cn(
              'p-3.5 rounded-xl border bg-slate-50/60 dark:bg-slate-900/40 hover:bg-slate-50 dark:hover:bg-slate-900 transition-colors',
              checked ? 'border-emerald-500 bg-emerald-50/30 dark:bg-emerald-950/20 ring-1 ring-emerald-500/20' : 'border-slate-200 dark:border-slate-800'
            ),
          disabled && 'opacity-60 cursor-not-allowed hover:bg-transparent',
          wrapperClassName
        )}
      >
        <div className="relative flex items-center pt-0.5">
          <input
            ref={ref}
            id={identifier.id}
            data-rakit={identifier['data-rakit']}
            type="radio"
            value={value}
            checked={checked}
            onChange={() => onChange?.(value)}
            disabled={disabled}
            className="sr-only peer"
            {...props}
          />
          <div
            className={cn(
              'rakit-radio rounded-full border flex items-center justify-center transition-all duration-150 shadow-2xs peer-focus-visible:ring-2 peer-focus-visible:ring-emerald-500/30 peer-focus-visible:ring-offset-1',
              identifier.className,
              circleSizeClasses[size],
              checked
                ? 'bg-emerald-600 border-emerald-600'
                : 'bg-white dark:bg-slate-900 border-slate-300 dark:border-slate-700 hover:border-slate-400',
              disabled && 'bg-slate-100 dark:bg-slate-800 border-slate-300 dark:border-slate-700 cursor-not-allowed',
              className
            )}
          >
            {checked && <div className={cn('rounded-full bg-white dark:bg-slate-100', innerDotClasses[size])} />}
          </div>
        </div>

        {(label || description) && (
          <div className="flex flex-col">
            {label && (
              <span
                className={cn(
                  'font-medium text-slate-800 transition-colors leading-snug',
                  size === 'xs' || size === 'sm' ? 'text-xs' : size === 'lg' ? 'text-base' : size === 'xl' ? 'text-lg' : 'text-sm',
                  disabled && 'text-slate-400'
                )}
              >
                {label}
              </span>
            )}
            {description && (
              <span
                className={cn(
                  'text-slate-500 text-xs mt-0.5 leading-normal',
                  disabled && 'text-slate-400'
                )}
              >
                {description}
              </span>
            )}
          </div>
        )}
      </label>
    );
  }
);

Radio.displayName = 'Radio';

// ============================================================================
// TYPES & INTERFACES
// ============================================================================
export type { RadioProps } from '../../../../types/ui/field/radio.types';
