import { forwardRef, useId } from 'react';

import { cn } from '../../../../utils/ui/cn';
import { useRakitConfig, getComponentIdentifier } from '../../../../config/RakitContext';

import type { SwitchProps } from '../../../../types/ui/field/switch.types';
import type { FieldSize } from '../../../../types/ui/field/fieldWrapper.types';

export const Switch = forwardRef<HTMLButtonElement, SwitchProps>(
  (
    {
      id: customId,
      checked = false,
      onChange,
      label,
      description,
      disabled = false,
      size = 'md',
      checkedIcon,
      uncheckedIcon,
      className,
      wrapperClassName,
    },
    ref
  ) => {
    const config = useRakitConfig();
    const generatedId = useId();
    const inputId = customId || generatedId;
    const identifier = getComponentIdentifier('switch', config, inputId);

    const trackSizeClasses: Record<FieldSize, string> = {
      xs: 'w-6 h-3.5 p-0.5',
      sm: 'w-8 h-4.5 p-0.5',
      md: 'w-11 h-6 p-0.5',
      lg: 'w-14 h-7.5 p-1',
      xl: 'w-16 h-8.5 p-1',
    };

    const thumbSizeClasses: Record<FieldSize, string> = {
      xs: 'w-2.5 h-2.5',
      sm: 'w-3.5 h-3.5',
      md: 'w-5 h-5',
      lg: 'w-5.5 h-5.5',
      xl: 'w-6.5 h-6.5',
    };

    const thumbTranslateClasses: Record<FieldSize, string> = {
      xs: checked ? 'translate-x-2.5' : 'translate-x-0',
      sm: checked ? 'translate-x-3.5' : 'translate-x-0',
      md: checked ? 'translate-x-5' : 'translate-x-0',
      lg: checked ? 'translate-x-6.5' : 'translate-x-0',
      xl: checked ? 'translate-x-7.5' : 'translate-x-0',
    };

    return (
      <div
        className={cn(
          'rakit-switch-wrapper flex items-start gap-3 select-none',
          disabled && 'opacity-60 cursor-not-allowed',
          wrapperClassName
        )}
      >
        <button
          ref={ref}
          id={identifier.id}
          data-rakit={identifier['data-rakit']}
          type="button"
          role="switch"
          aria-checked={checked}
          disabled={disabled}
          onClick={() => !disabled && onChange?.(!checked)}
          className={cn(
            'rakit-switch relative inline-flex shrink-0 rounded-full transition-colors duration-200 ease-in-out focus:outline-none focus-visible:ring-2 focus-visible:ring-emerald-500/30 focus-visible:ring-offset-1 cursor-pointer',
            identifier.className,
            trackSizeClasses[size],
            checked ? 'bg-emerald-600' : 'bg-slate-300 dark:bg-slate-700 hover:bg-slate-400/80',
            disabled && 'cursor-not-allowed hover:bg-slate-300 dark:hover:bg-slate-700',
            className
          )}
        >
          <span
            className={cn(
              'pointer-events-none inline-flex items-center justify-center rounded-full bg-white dark:bg-slate-100 shadow-sm ring-0 transition duration-200 ease-in-out',
              thumbSizeClasses[size],
              thumbTranslateClasses[size]
            )}
          >
            {checked ? checkedIcon : uncheckedIcon}
          </span>
        </button>

        {(label || description) && (
          <label htmlFor={generatedId} className="flex flex-col cursor-pointer">
            {label && (
              <span
                className={cn(
                  'font-medium text-slate-800 transition-colors leading-snug',
                  size === 'xs' || size === 'sm' ? 'text-xs' : size === 'lg' ? 'text-base' : size === 'xl' ? 'text-lg' : 'text-sm',
                  disabled && 'text-slate-400'
                )}
              >
                {label}
              </span>
            )}
            {description && (
              <span
                className={cn(
                  'text-slate-500 text-xs mt-0.5 leading-normal',
                  disabled && 'text-slate-400'
                )}
              >
                {description}
              </span>
            )}
          </label>
        )}
      </div>
    );
  }
);

Switch.displayName = 'Switch';

// ============================================================================
// TYPES & INTERFACES
// ============================================================================
export type { SwitchProps } from '../../../../types/ui/field/switch.types';
