import { forwardRef, useId, useState } from 'react';
import { Eye, EyeOff, X } from 'lucide-react';

import { FieldWrapper } from '../field-wrapper';
import { cn } from '../../../../utils/ui/cn';
import { useRakitConfig, getComponentIdentifier } from '../../../../config/RakitContext';

import type { TextFieldProps } from '../../../../types/ui/field/textField.types';
import type { FieldSize } from '../../../../types/ui/field/fieldWrapper.types';

export const TextField = forwardRef<HTMLInputElement, TextFieldProps>(
  (
    {
      type = 'text',
      id: customId,
      name,
      value,
      defaultValue,
      onChange,
      placeholder,
      disabled,
      readOnly,
      required,
      optional,
      label,
      error,
      helperText,
      hint,
      size,
      layout = 'vertical',
      leftIcon,
      rightIcon,
      prefixText,
      suffixText,
      clearable,
      onClear,
      isPasswordToggle = true,
      wrapperClassName,
      inputWrapperClassName,
      className,
      ...props
    },
    ref
  ) => {
    const config = useRakitConfig();
    const fieldConfig = config?.components?.field;
    const resolvedSize: FieldSize = size || fieldConfig?.defaultSize || 'md';

    const generatedId = useId();
    const inputId = customId || generatedId;
    const identifier = getComponentIdentifier('input', config, customId);

    const [internalValue, setInternalValue] = useState(defaultValue ?? '');
    const isControlled = value !== undefined;
    const currentValue = isControlled ? value : internalValue;
    const hasValue = Boolean(currentValue !== undefined && String(currentValue).length > 0);

    const [showPassword, setShowPassword] = useState(false);
    const isPassword = type === 'password';
    const effectiveType = isPassword && showPassword ? 'text' : type;

    const heightClasses: Record<FieldSize, string> = {
      xs: 'h-7 min-h-[28px]',
      sm: 'h-8 min-h-[32px]',
      md: 'h-10 min-h-[40px]',
      lg: 'h-11 min-h-[44px]',
      xl: 'h-12 min-h-[48px]',
    };

    const textSizeClasses: Record<FieldSize, string> = {
      xs: 'text-xs',
      sm: 'text-xs',
      md: 'text-sm',
      lg: 'text-base',
      xl: 'text-lg',
    };

    const roundedClasses: Record<FieldSize, string> = {
      xs: 'rounded-md',
      sm: 'rounded-lg',
      md: 'rounded-lg',
      lg: 'rounded-xl',
      xl: 'rounded-xl',
    };

    const paddingClasses: Record<FieldSize, string> = {
      xs: cn(
        prefixText ? 'pl-2' : leftIcon ? 'pl-1.5' : 'pl-2.5',
        suffixText ? 'pr-2' : rightIcon || (isPassword && isPasswordToggle) || (clearable && hasValue) ? 'pr-1.5' : 'pr-2.5'
      ),
      sm: cn(
        prefixText ? 'pl-2.5' : leftIcon ? 'pl-2' : 'pl-3',
        suffixText ? 'pr-2.5' : rightIcon || (isPassword && isPasswordToggle) || (clearable && hasValue) ? 'pr-2' : 'pr-3'
      ),
      md: cn(
        prefixText ? 'pl-3' : leftIcon ? 'pl-2.5' : 'pl-3.5',
        suffixText ? 'pr-3' : rightIcon || (isPassword && isPasswordToggle) || (clearable && hasValue) ? 'pr-2.5' : 'pr-3.5'
      ),
      lg: cn(
        prefixText ? 'pl-3.5' : leftIcon ? 'pl-3' : 'pl-4',
        suffixText ? 'pr-3.5' : rightIcon || (isPassword && isPasswordToggle) || (clearable && hasValue) ? 'pr-3' : 'pr-4'
      ),
      xl: cn(
        prefixText ? 'pl-4' : leftIcon ? 'pl-3.5' : 'pl-5',
        suffixText ? 'pr-4' : rightIcon || (isPassword && isPasswordToggle) || (clearable && hasValue) ? 'pr-3.5' : 'pr-5'
      ),
    };

    const iconSizeClasses: Record<FieldSize, string> = {
      xs: 'w-3 h-3',
      sm: 'w-3.5 h-3.5',
      md: 'w-4 h-4',
      lg: 'w-5 h-5',
      xl: 'w-5.5 h-5.5',
    };

    const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      if (!isControlled) {
        setInternalValue(e.target.value);
      }
      onChange?.(e);
    };

    const handleClear = () => {
      if (!isControlled) {
        setInternalValue('');
      }
      onClear?.();
    };

    const inputNode = (
      <div
        className={cn(
          'group/input-field relative flex items-center w-full transition-colors duration-150 overflow-hidden',
          identifier.className,
          heightClasses[resolvedSize],
          roundedClasses[resolvedSize],
          'bg-white border',
          error
            ? 'border-rose-300 bg-rose-50/20 focus-within:border-rose-500 focus-within:ring-1 focus-within:ring-rose-500'
            : 'border-slate-300 hover:border-slate-400 focus-within:border-emerald-600 focus-within:ring-1 focus-within:ring-emerald-600',
          disabled && 'opacity-60 bg-slate-50/80 cursor-not-allowed border-slate-200',
          fieldConfig?.className,
          inputWrapperClassName
        )}
        data-rakit="field"
        data-size={resolvedSize}
        {...(identifier.id ? { id: identifier.id } : {})}
      >
        {prefixText && (
          <span
            className={cn(
              'inline-flex items-center justify-center self-stretch shrink-0 font-mono font-medium select-none transition-colors',
              'border-r border-slate-200 bg-slate-50 text-slate-600 group-focus-within/input-field:border-emerald-600/40 group-focus-within/input-field:bg-emerald-50/40 group-focus-within/input-field:text-emerald-800',
              resolvedSize === 'xs' ? 'px-2 text-[11px]' : resolvedSize === 'sm' ? 'px-2.5 text-xs' : resolvedSize === 'lg' ? 'px-3.5 text-base' : resolvedSize === 'xl' ? 'px-4 text-lg' : 'px-3 text-sm'
            )}
          >
            {prefixText}
          </span>
        )}

        {leftIcon && !prefixText && (
          <div className="pl-2.5 flex items-center pointer-events-none text-slate-400 group-focus-within/input-field:text-emerald-600 transition-colors shrink-0">
            <span className={iconSizeClasses[resolvedSize]}>{leftIcon}</span>
          </div>
        )}

        <input
          ref={ref}
          id={inputId}
          name={name}
          type={effectiveType}
          value={value}
          defaultValue={defaultValue}
          onChange={handleChange}
          placeholder={placeholder}
          disabled={disabled}
          readOnly={readOnly}
          required={required}
          className={cn(
            'w-full flex-1 h-full min-w-0 bg-transparent border-0 py-0 outline-none focus:outline-none focus:ring-0 text-slate-800 placeholder:text-slate-400 font-medium',
            textSizeClasses[resolvedSize],
            paddingClasses[resolvedSize],
            disabled && 'cursor-not-allowed',
            className
          )}
          {...props}
        />

        {/* Right Controls: Clear button, Password toggle, rightIcon */}
        {((clearable && hasValue && !disabled && !readOnly) ||
          (isPassword && isPasswordToggle && !disabled) ||
          (rightIcon && !isPassword)) && (
          <div className="flex items-center gap-1 pr-2 shrink-0">
            {clearable && hasValue && !disabled && !readOnly && (
              <button
                type="button"
                onClick={handleClear}
                className="p-1 rounded-md text-slate-400 hover:text-slate-600 hover:bg-slate-100 transition-colors cursor-pointer"
                aria-label="Bersihkan input"
              >
                <X className={iconSizeClasses[resolvedSize]} />
              </button>
            )}

            {isPassword && isPasswordToggle && !disabled && (
              <button
                type="button"
                onClick={() => setShowPassword((prev) => !prev)}
                className="p-1 rounded-md text-slate-400 hover:text-slate-600 hover:bg-slate-100 transition-colors cursor-pointer"
                aria-label={showPassword ? 'Sembunyikan password' : 'Tampilkan password'}
              >
                {showPassword ? <EyeOff className={iconSizeClasses[resolvedSize]} /> : <Eye className={iconSizeClasses[resolvedSize]} />}
              </button>
            )}

            {rightIcon && !isPassword && !clearable && (
              <div className="pointer-events-none text-slate-400 group-focus-within/input-field:text-emerald-600 transition-colors">
                <span className={iconSizeClasses[resolvedSize]}>{rightIcon}</span>
              </div>
            )}
          </div>
        )}

        {suffixText && (
          <span
            className={cn(
              'inline-flex items-center justify-center self-stretch shrink-0 font-mono font-medium select-none transition-colors',
              'border-l border-slate-200 bg-slate-50 text-slate-600 group-focus-within/input-field:border-emerald-600/40 group-focus-within/input-field:bg-emerald-50/40 group-focus-within/input-field:text-emerald-800',
              resolvedSize === 'xs' ? 'px-2 text-[11px]' : resolvedSize === 'sm' ? 'px-2.5 text-xs' : resolvedSize === 'lg' ? 'px-3.5 text-base' : resolvedSize === 'xl' ? 'px-4 text-lg' : 'px-3 text-sm'
            )}
          >
            {suffixText}
          </span>
        )}
      </div>
    );

    if (label || error || helperText || hint) {
      return (
        <FieldWrapper
          htmlFor={inputId}
          label={label}
          error={error}
          helperText={helperText}
          hint={hint}
          required={required}
          optional={optional}
          disabled={disabled}
          size={resolvedSize}
          layout={layout}
          className={wrapperClassName}
        >
          {inputNode}
        </FieldWrapper>
      );
    }

    return inputNode;
  }
);

TextField.displayName = 'TextField';

// ============================================================================
// TYPES & INTERFACES
// ============================================================================
export type { TextFieldProps } from '../../../../types/ui/field/textField.types';
