import React, { useMemo } from 'react';
import type { ReactNode } from 'react';
import { useRunner } from 'react-runner';
import { AlertCircle } from 'lucide-react';

import * as LucideIcons from 'lucide-react';

// Core UI components available in live preview scope
import { Button } from '../button';
import { Badge } from '../badge';
import { Card } from '../card';
import { TextField } from '../field/text-field/TextField';
import { Select } from '../field/select/Select';
import { Checkbox } from '../field/checkbox/Checkbox';
import { Switch } from '../field/switch/Switch';
import { Radio, RadioGroup } from '../field/radio';
import { TextArea } from '../field/textarea/TextArea';
import { Autocomplete } from '../field/autocomplete/Autocomplete';
import { MultiSelect } from '../field/multi-select/MultiSelect';
import { Tabs } from '../tabs';
import { Table } from '../table';
import { Modal } from '../modal';
import { Grid } from '../grid';
import { Typography } from '../typography';
import { SegmentedControl } from '../segmented-control';
import { EmptyState } from '../empty-state';
import { Breadcrumb } from '../breadcrumb';

export interface LivePreviewProps {
  code: string;
  scope?: Record<string, any>;
  className?: string;
  fallback?: ReactNode;
  onError?: (error: Error | string | null) => void;
}

const RAKIT_COMPONENTS = {
  Button,
  Badge,
  Card,
  TextField,
  Select,
  Checkbox,
  Switch,
  Radio,
  RadioGroup,
  TextArea,
  Autocomplete,
  MultiSelect,
  Tabs,
  Table,
  Modal,
  Grid,
  Typography,
  SegmentedControl,
  EmptyState,
  Breadcrumb,
};

const ID_REGEX = /^[a-zA-Z_$][a-zA-Z0-9_$]*$/;

/**
 * Normalizes user code to ensure compatibility with react-runner compiler:
 * 1. Checks if export default exists.
 * 2. If missing, automatically exports named function or const component as default.
 */
function normalizeCode(rawCode: string): string {
  if (!rawCode) return '';
  let code = rawCode.trim();

  // If already contains export default or is bare JSX tag, keep as is
  if (/export\s+default\s+/.test(code) || /^\s*<[a-zA-Z]/.test(code)) {
    return code;
  }

  // Check for named function or const component (e.g. export function App() or function App())
  const namedMatch = code.match(/(?:export\s+)?(?:function|const|class)\s+([A-Z][a-zA-Z0-9_$]*)/);
  if (namedMatch && namedMatch[1]) {
    code += `\nexport default ${namedMatch[1]};`;
  }

  return code;
}

export function LivePreview({
  code,
  scope: customScope,
  className = '',
  fallback = null,
  onError,
}: LivePreviewProps) {
  // Construct execution scope with React hooks, Lucide icons, and Rakit UI components.
  // Crucially sanitizes scope keys: only valid JS identifiers are passed at top-level.
  // Any keys with '@', '/', '-', '.' (like module names) are placed inside scope.import.
  const scope = useMemo(() => {
    const userGlobals: Record<string, any> = {};
    const userImports: Record<string, any> = {};

    if (customScope) {
      for (const [key, value] of Object.entries(customScope)) {
        if (key === 'import' && value && typeof value === 'object') {
          Object.assign(userImports, value);
        } else if (ID_REGEX.test(key)) {
          userGlobals[key] = value;
        } else {
          // Module specifiers like '@zarr20/rakit-routes', 'styles.css'
          userImports[key] = value;
        }
      }
    }

    // Filter React exports to ensure only valid identifier names
    const reactGlobals: Record<string, any> = {};
    for (const [k, v] of Object.entries(React)) {
      if (ID_REGEX.test(k)) {
        reactGlobals[k] = v;
      }
    }

    // Filter Lucide icons
    const iconGlobals: Record<string, any> = {};
    for (const [k, v] of Object.entries(LucideIcons)) {
      if (ID_REGEX.test(k)) {
        iconGlobals[k] = v;
      }
    }

    return {
      React,
      ...reactGlobals,
      ...RAKIT_COMPONENTS,
      ...iconGlobals,
      ...userGlobals,
      import: {
        react: React,
        'react/jsx-runtime': React,
        'lucide-react': LucideIcons,
        '@zarr20/rakit-ui': {
          ...RAKIT_COMPONENTS,
          ...(userImports['@zarr20/rakit-ui'] || {}),
        },
        '@zarr20/rakit-ui/styles.css': {},
        '@zarr20/rakit-ui/style.css': {},
        '@zarr20/rakit-routes': userImports['@zarr20/rakit-routes'] || {},
        ...userImports,
      },
    };
  }, [customScope]);

  const normalizedCode = useMemo(() => {
    return normalizeCode(code);
  }, [code]);

  const { element, error } = useRunner({
    code: normalizedCode,
    scope,
  });

  React.useEffect(() => {
    onError?.(error || null);
  }, [error, onError]);

  if (error) {
    return (
      <div className="w-full h-full p-4 flex flex-col justify-center items-center">
        <div className="w-full max-w-xl p-4 rounded-xl bg-rose-50 dark:bg-rose-950/70 border border-rose-200 dark:border-rose-900/80 shadow-2xs text-rose-800 dark:text-rose-200">
          <div className="flex items-center gap-2 font-semibold text-xs text-rose-700 dark:text-rose-300 mb-2">
            <AlertCircle className="w-4 h-4 text-rose-500 shrink-0" />
            <span>Kompilasi / Runtime Error:</span>
          </div>
          <pre className="font-mono text-xs whitespace-pre-wrap leading-relaxed text-rose-900 dark:text-rose-200 overflow-x-auto max-h-48 p-2 rounded-lg bg-rose-100/60 dark:bg-rose-900/40">
            {typeof error === 'string' ? error : (error as any)?.message || String(error)}
          </pre>
        </div>
      </div>
    );
  }

  return (
    <div className={`w-full h-full flex flex-col ${className}`}>
      {element || fallback}
    </div>
  );
}
