import React from 'react';
import { BreadcrumbPageProps } from '../../../types/ui/breadcrumb.types';

export const BreadcrumbPage: React.FC<BreadcrumbPageProps> = ({
  className = '',
  children,
  ...props
}) => {
  const classes = [
    'rakit-breadcrumb-page font-semibold text-slate-900 dark:text-slate-100',
    className,
  ]
    .filter(Boolean)
    .join(' ');

  return (
    <span
      role="link"
      aria-disabled="true"
      aria-current="page"
      className={classes}
      data-rakit="breadcrumb-page"
      {...props}
    >
      {children}
    </span>
  );
};
