import { cn } from '../../../utils/ui/cn';
import { useSidebar } from './SidebarContext';
import type { SidebarGroupProps } from '../../../types/ui/sidebar.types';

export function SidebarGroup({
  title,
  className = '',
  children,
  ...rest
}: SidebarGroupProps) {
  const { collapsed } = useSidebar();

  return (
    <div
      className={cn('rakit-sidebar-group space-y-1', className)}
      data-rakit="sidebar-group"
      data-collapsed={collapsed}
      {...rest}
    >
      {title && (
        <>
          {!collapsed ? (
            <div className="px-2 mb-1 text-[10.5px] font-mono font-bold uppercase tracking-wider text-slate-400 dark:text-slate-500 select-none truncate">
              {title}
            </div>
          ) : (
            <div className="my-1.5 border-t border-slate-100 dark:border-slate-800/80" />
          )}
        </>
      )}
      <div className="space-y-0.5">{children}</div>
    </div>
  );
}
