import { useState, useMemo } from 'react';
import type { ReactNode } from 'react';
import {
  Code2,
  Eye,
  Columns,
  Monitor,
  Tablet,
  Smartphone,
  RotateCcw,
  Copy,
  Check,
  Sun,
  Moon,
} from 'lucide-react';

import { CodeEditor } from './CodeEditor';
import { LivePreview } from './LivePreview';
import { Badge } from '../badge';
import { Button } from '../button';
import { cn } from '../../../utils/ui/cn';

import type { CodeEditorTheme } from '../../../types/ui/code-editor.types';

export type LivePlaygroundViewport = 'desktop' | 'tablet' | 'mobile';

export interface LivePlaygroundProps {
  initialCode?: string;
  code?: string;
  onChange?: (code: string) => void;
  scope?: Record<string, any>;
  theme?: CodeEditorTheme;
  defaultViewMode?: 'split' | 'code' | 'preview';
  defaultViewport?: LivePlaygroundViewport;
  title?: ReactNode;
  height?: string | number;
  readOnly?: boolean;
  showToolbar?: boolean;
  className?: string;
  previewClassName?: string;
  editorClassName?: string;
  extraActions?: ReactNode;
}

export function LivePlayground({
  initialCode = `import React, { useState } from 'react';
import { Button, Card, Badge } from '@zarr20/rakit-ui';
import { Sparkles, Heart } from 'lucide-react';

export default function App() {
  const [likes, setLikes] = useState(0);

  return (
    <Card variant="bordered" padding="large" className="max-w-md mx-auto my-6 text-center shadow-lg">
      <div className="flex items-center justify-between pb-3 border-b border-slate-100 dark:border-slate-800">
        <span className="font-semibold text-slate-800 dark:text-slate-100 flex items-center gap-1.5">
          <Sparkles className="w-4 h-4 text-emerald-500" />
          Rakit Live Preview
        </span>
        <Badge variant="primary" size="xs">Live TSX</Badge>
      </div>

      <p className="text-slate-600 dark:text-slate-300 text-sm mt-4">
        Edit kode TSX di sebelah kiri dan lihat hasil rendering secara langsung!
      </p>

      <div className="mt-6 flex justify-center items-center gap-3">
        <Button
          variant="primary"
          size="md"
          leftIcon={<Heart className="w-4 h-4 text-rose-400 fill-rose-400" />}
          onClick={() => setLikes(likes + 1)}
        >
          Suka ({likes})
        </Button>
        <Button
          variant="outline"
          size="md"
          onClick={() => setLikes(0)}
        >
          Reset
        </Button>
      </div>
    </Card>
  );
}`,
  code: controlledCode,
  onChange,
  scope,
  theme: controlledTheme,
  defaultViewMode = 'split',
  defaultViewport = 'desktop',
  title = 'App.tsx',
  height = '580px',
  readOnly = false,
  showToolbar = true,
  className = '',
  previewClassName = '',
  editorClassName = '',
  extraActions,
}: LivePlaygroundProps) {
  const [internalCode, setInternalCode] = useState<string>(initialCode);
  const [viewMode, setViewMode] = useState<'split' | 'code' | 'preview'>(defaultViewMode);
  const [viewport, setViewport] = useState<LivePlaygroundViewport>(defaultViewport);
  const [internalTheme, setInternalTheme] = useState<CodeEditorTheme>(controlledTheme || 'dark');
  const [copied, setCopied] = useState(false);

  const activeCode = controlledCode !== undefined ? controlledCode : internalCode;
  const isDark = (controlledTheme !== undefined ? controlledTheme : internalTheme) === 'dark';

  const handleCodeChange = (newCode: string) => {
    if (controlledCode === undefined) {
      setInternalCode(newCode);
    }
    onChange?.(newCode);
  };

  const handleReset = () => {
    handleCodeChange(initialCode);
  };

  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText(activeCode);
      setCopied(true);
      setTimeout(() => setCopied(false), 1500);
    } catch {
      // Ignored
    }
  };

  const toggleTheme = () => {
    setInternalTheme((prev) => (prev === 'dark' ? 'light' : 'dark'));
  };

  // Viewport constraint style
  const viewportMaxWidth = useMemo(() => {
    switch (viewport) {
      case 'mobile':
        return '375px';
      case 'tablet':
        return '768px';
      case 'desktop':
      default:
        return '100%';
    }
  }, [viewport]);

  return (
    <div
      className={cn(
        'w-full flex flex-col rounded-2xl border overflow-hidden shadow-xl transition-colors',
        isDark ? 'bg-slate-950 border-slate-800' : 'bg-white border-slate-200/90',
        className
      )}
    >
      {/* Top Toolbar */}
      {showToolbar && (
        <div
          className={cn(
            'w-full flex flex-wrap items-center justify-between gap-2 px-3.5 py-2.5 border-b select-none transition-colors shrink-0',
            isDark
              ? 'bg-slate-900 border-slate-800 text-slate-200'
              : 'bg-slate-50 border-slate-200/80 text-slate-800'
          )}
        >
          {/* Left: Title & Live Badge */}
          <div className="flex items-center gap-2.5 shrink-0">
            <span className="font-mono text-xs font-semibold flex items-center gap-1.5">
              <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse" />
              {title}
            </span>
            <Badge variant="subtle" size="xs" className="font-mono text-[10px]">
              Live TSX
            </Badge>
          </div>

          {/* Center: View Mode (Split, Code, Preview) & Viewport Mode */}
          <div className="flex items-center gap-2 flex-wrap">
            {/* View Mode Switcher */}
            <div
              className={cn(
                'flex items-center p-0.5 rounded-lg border text-xs',
                isDark ? 'bg-slate-800/80 border-slate-700/60' : 'bg-slate-200/70 border-slate-300/80'
              )}
            >
              <button
                type="button"
                onClick={() => setViewMode('split')}
                className={cn(
                  'flex items-center gap-1 px-2.5 py-1 rounded-md text-xs font-medium cursor-pointer transition-colors',
                  viewMode === 'split'
                    ? isDark
                      ? 'bg-slate-700 text-white shadow-2xs font-semibold'
                      : 'bg-white text-slate-900 shadow-2xs font-semibold'
                    : isDark
                    ? 'text-slate-400 hover:text-white'
                    : 'text-slate-600 hover:text-slate-900'
                )}
                title="Split View (Editor & Live Preview)"
              >
                <Columns className="w-3.5 h-3.5" />
                <span className="hidden sm:inline">Split</span>
              </button>

              <button
                type="button"
                onClick={() => setViewMode('code')}
                className={cn(
                  'flex items-center gap-1 px-2.5 py-1 rounded-md text-xs font-medium cursor-pointer transition-colors',
                  viewMode === 'code'
                    ? isDark
                      ? 'bg-slate-700 text-white shadow-2xs font-semibold'
                      : 'bg-white text-slate-900 shadow-2xs font-semibold'
                    : isDark
                    ? 'text-slate-400 hover:text-white'
                    : 'text-slate-600 hover:text-slate-900'
                )}
                title="Code Editor Only"
              >
                <Code2 className="w-3.5 h-3.5" />
                <span className="hidden sm:inline">Code</span>
              </button>

              <button
                type="button"
                onClick={() => setViewMode('preview')}
                className={cn(
                  'flex items-center gap-1 px-2.5 py-1 rounded-md text-xs font-medium cursor-pointer transition-colors',
                  viewMode === 'preview'
                    ? isDark
                      ? 'bg-slate-700 text-white shadow-2xs font-semibold'
                      : 'bg-white text-slate-900 shadow-2xs font-semibold'
                    : isDark
                    ? 'text-slate-400 hover:text-white'
                    : 'text-slate-600 hover:text-slate-900'
                )}
                title="Live Preview Only"
              >
                <Eye className="w-3.5 h-3.5" />
                <span className="hidden sm:inline">Preview</span>
              </button>
            </div>

            {/* Viewport switcher (when preview is visible) */}
            {viewMode !== 'code' && (
              <div
                className={cn(
                  'flex items-center p-0.5 rounded-lg border text-xs',
                  isDark ? 'bg-slate-800/80 border-slate-700/60' : 'bg-slate-200/70 border-slate-300/80'
                )}
              >
                <button
                  type="button"
                  onClick={() => setViewport('desktop')}
                  className={cn(
                    'p-1.5 rounded-md cursor-pointer transition-colors',
                    viewport === 'desktop'
                      ? isDark
                        ? 'bg-slate-700 text-white shadow-2xs'
                        : 'bg-white text-slate-900 shadow-2xs'
                      : isDark
                      ? 'text-slate-400 hover:text-white'
                      : 'text-slate-600 hover:text-slate-900'
                  )}
                  title="Desktop (100%)"
                >
                  <Monitor className="w-3.5 h-3.5" />
                </button>

                <button
                  type="button"
                  onClick={() => setViewport('tablet')}
                  className={cn(
                    'p-1.5 rounded-md cursor-pointer transition-colors',
                    viewport === 'tablet'
                      ? isDark
                        ? 'bg-slate-700 text-white shadow-2xs'
                        : 'bg-white text-slate-900 shadow-2xs'
                      : isDark
                      ? 'text-slate-400 hover:text-white'
                      : 'text-slate-600 hover:text-slate-900'
                  )}
                  title="Tablet (768px)"
                >
                  <Tablet className="w-3.5 h-3.5" />
                </button>

                <button
                  type="button"
                  onClick={() => setViewport('mobile')}
                  className={cn(
                    'p-1.5 rounded-md cursor-pointer transition-colors',
                    viewport === 'mobile'
                      ? isDark
                        ? 'bg-slate-700 text-white shadow-2xs'
                        : 'bg-white text-slate-900 shadow-2xs'
                      : isDark
                      ? 'text-slate-400 hover:text-white'
                      : 'text-slate-600 hover:text-slate-900'
                  )}
                  title="Mobile (375px)"
                >
                  <Smartphone className="w-3.5 h-3.5" />
                </button>
              </div>
            )}
          </div>

          {/* Right: Actions */}
          <div className="flex items-center gap-1.5 ml-auto shrink-0">
            {/* Theme Toggle */}
            <Button
              type="button"
              variant="outline"
              size="xs"
              onClick={toggleTheme}
              leftIcon={
                isDark ? (
                  <Sun className="w-3.5 h-3.5 text-amber-400" />
                ) : (
                  <Moon className="w-3.5 h-3.5 text-slate-600" />
                )
              }
              title={`Switch to ${isDark ? 'light' : 'dark'} mode`}
            />

            {/* Reset Code */}
            {!readOnly && (
              <Button
                type="button"
                variant="outline"
                size="xs"
                onClick={handleReset}
                leftIcon={<RotateCcw className="w-3.5 h-3.5 text-slate-400" />}
                title="Reset to initial code"
              >
                <span className="hidden sm:inline">Reset</span>
              </Button>
            )}

            {/* Copy Code */}
            <Button
              type="button"
              variant="outline"
              size="xs"
              onClick={handleCopy}
              leftIcon={
                copied ? <Check className="w-3.5 h-3.5 text-emerald-500" /> : <Copy className="w-3.5 h-3.5" />
              }
              title="Copy code"
            >
              <span className="hidden sm:inline">{copied ? 'Copied' : 'Copy'}</span>
            </Button>

            {extraActions}
          </div>
        </div>
      )}

      {/* Main Body */}
      <div
        style={{
          height: typeof height === 'number' ? `${height}px` : height,
        }}
        className="w-full flex flex-col lg:flex-row overflow-hidden relative"
      >
        {/* Left Pane: Code Editor */}
        {(viewMode === 'split' || viewMode === 'code') && (
          <div
            className={cn(
              'h-full overflow-hidden transition-all',
              viewMode === 'split'
                ? 'w-full lg:w-1/2 border-b lg:border-b-0 lg:border-r border-slate-800/80'
                : 'w-full',
              editorClassName
            )}
          >
            <CodeEditor
              value={activeCode}
              onChange={handleCodeChange}
              language="tsx"
              theme={isDark ? 'dark' : 'light'}
              readOnly={readOnly}
              showToolbar={false}
              showLineNumbers={true}
              height="100%"
              className="border-0 rounded-none h-full"
            />
          </div>
        )}

        {/* Right Pane: Live Preview */}
        {(viewMode === 'split' || viewMode === 'preview') && (
          <div
            className={cn(
              'h-full flex flex-col items-center justify-start overflow-auto p-4 transition-all',
              viewMode === 'split' ? 'w-full lg:w-1/2' : 'w-full',
              isDark
                ? 'bg-slate-900/50 [background-image:radial-gradient(#334155_1px,transparent_1px)]'
                : 'bg-slate-50/70 [background-image:radial-gradient(#e2e8f0_1px,transparent_1px)]',
              previewClassName
            )}
            style={{ backgroundSize: '16px 16px' }}
          >
            <div
              className={cn(
                'w-full flex-1 flex flex-col transition-all duration-300 ease-in-out',
                viewport !== 'desktop'
                  ? 'border-2 border-slate-700/80 rounded-2xl shadow-2xl bg-white dark:bg-slate-900 overflow-hidden my-auto'
                  : 'rounded-xl overflow-hidden'
              )}
              style={{
                maxWidth: viewportMaxWidth,
                minHeight: viewport !== 'desktop' ? '540px' : 'auto',
              }}
            >
              {viewport !== 'desktop' && (
                <div className="bg-slate-900 px-3 py-1 flex items-center justify-between text-[11px] font-mono text-slate-400 border-b border-slate-800">
                  <span>Viewport: {viewport.toUpperCase()}</span>
                  <span>{viewport === 'mobile' ? '375 × 667' : '768 × 1024'}</span>
                </div>
              )}

              <div className="flex-1 w-full p-4 overflow-auto">
                <LivePreview code={activeCode} scope={scope} />
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

export const CodePlayground = LivePlayground;
