import { useMemo } from 'react';
import { cn } from '../../../utils/ui/cn';
import { useRakitConfig, getComponentIdentifier } from '../../../config/RakitContext';
import { STACK_LAYER_CLASSES } from '../../../types/ui/layout.types';
import type { SidebarProps, SidebarContextValue } from '../../../types/ui/sidebar.types';

import { SidebarContext } from './SidebarContext';
import { SidebarHeader } from './SidebarHeader';
import { SidebarToggle } from './SidebarToggle';
import { SidebarNav } from './SidebarNav';
import { SidebarGroup } from './SidebarGroup';
import { SidebarItem } from './SidebarItem';
import { SidebarFooter } from './SidebarFooter';
import { SidebarSeparator } from './SidebarSeparator';
import { Drawer } from '../drawer/Drawer';

export function Sidebar({
  id,
  isOpen = false,
  onClose,
  width = 'w-64',
  collapsed = false,
  onToggleCollapse,
  collapsedWidth = 'w-16',
  position = 'left',
  mobileMode = 'drawer',
  bordered = true,
  layer = 'sidebar',
  className = '',
  children,
}: SidebarProps) {
  const config = useRakitConfig();
  const identifier = getComponentIdentifier('sidebar', config, id);
  const sidebarOverride = config.components?.sidebar;

  const desktopLayerClass = STACK_LAYER_CLASSES[layer] || 'z-30';
  const currentWidth = collapsed ? collapsedWidth : width;

  const contextValue = useMemo<SidebarContextValue>(
    () => ({
      collapsed,
      isOpen,
      onClose,
      onToggleCollapse,
      position,
    }),
    [collapsed, isOpen, onClose, onToggleCollapse, position]
  );

  const mobileDrawerContextValue = useMemo<SidebarContextValue>(
    () => ({
      collapsed: false, // Mobile drawer always expanded for best touch ergonomics
      isOpen,
      onClose,
      onToggleCollapse,
      position,
    }),
    [isOpen, onClose, onToggleCollapse, position]
  );

  return (
    <>
      {/* Desktop Persistent Sidebar */}
      <SidebarContext.Provider value={contextValue}>
        <aside
          id={identifier.id}
          data-rakit={identifier['data-rakit']}
          data-collapsed={collapsed}
          data-open={isOpen}
          style={sidebarOverride?.style}
          className={cn(
            // Semantic class
            'rakit-sidebar',
            identifier.className,

            // Base structure
            'hidden md:flex flex-col h-full min-h-0 shrink-0 transition-all duration-200 ease-out',
            'bg-white dark:bg-slate-900 transition-colors',

            // Border
            bordered &&
              (position === 'left'
                ? 'border-r border-slate-200 dark:border-slate-800'
                : 'border-l border-slate-200 dark:border-slate-800'),

            // Desktop behavior
            desktopLayerClass,
            currentWidth,

            sidebarOverride?.className,
            className
          )}
        >
          {children}
        </aside>
      </SidebarContext.Provider>

      {/* Mobile Drawer using Drawer component */}
      {mobileMode === 'drawer' && onClose && (
        <Drawer
          isOpen={isOpen}
          onClose={onClose}
          placement={position === 'right' ? 'right' : 'left'}
          size="sm"
          bordered={bordered}
          className="md:hidden"
          contentClassName="p-0 overflow-hidden flex flex-col h-full"
        >
          <SidebarContext.Provider value={mobileDrawerContextValue}>
            <div className="flex flex-col h-full min-h-0 bg-white dark:bg-slate-900 transition-colors">
              {children}
            </div>
          </SidebarContext.Provider>
        </Drawer>
      )}
    </>
  );
}

// Compound component attachments
Sidebar.Header = SidebarHeader;
Sidebar.Toggle = SidebarToggle;
Sidebar.Nav = SidebarNav;
Sidebar.Group = SidebarGroup;
Sidebar.Item = SidebarItem;
Sidebar.Footer = SidebarFooter;
Sidebar.Separator = SidebarSeparator;
Sidebar.Context = SidebarContext;
