import { cn } from '../../../utils/ui/cn';
import { useRakitConfig, getComponentIdentifier } from '../../../config/RakitContext';
import { GridCol } from './GridCol';
import type { GridColsNumber, GridGap, GridProps, ResponsiveProp } from '../../../types/ui/grid.types';

const colsClasses: Record<GridColsNumber, string> = {
  1: 'grid-cols-1',
  2: 'grid-cols-2',
  3: 'grid-cols-3',
  4: 'grid-cols-4',
  5: 'grid-cols-5',
  6: 'grid-cols-6',
  7: 'grid-cols-7',
  8: 'grid-cols-8',
  9: 'grid-cols-9',
  10: 'grid-cols-10',
  11: 'grid-cols-11',
  12: 'grid-cols-12',
};

const smColsClasses: Record<GridColsNumber, string> = {
  1: 'sm:grid-cols-1',
  2: 'sm:grid-cols-2',
  3: 'sm:grid-cols-3',
  4: 'sm:grid-cols-4',
  5: 'sm:grid-cols-5',
  6: 'sm:grid-cols-6',
  7: 'sm:grid-cols-7',
  8: 'sm:grid-cols-8',
  9: 'sm:grid-cols-9',
  10: 'sm:grid-cols-10',
  11: 'sm:grid-cols-11',
  12: 'sm:grid-cols-12',
};

const mdColsClasses: Record<GridColsNumber, string> = {
  1: 'md:grid-cols-1',
  2: 'md:grid-cols-2',
  3: 'md:grid-cols-3',
  4: 'md:grid-cols-4',
  5: 'md:grid-cols-5',
  6: 'md:grid-cols-6',
  7: 'md:grid-cols-7',
  8: 'md:grid-cols-8',
  9: 'md:grid-cols-9',
  10: 'md:grid-cols-10',
  11: 'md:grid-cols-11',
  12: 'md:grid-cols-12',
};

const lgColsClasses: Record<GridColsNumber, string> = {
  1: 'lg:grid-cols-1',
  2: 'lg:grid-cols-2',
  3: 'lg:grid-cols-3',
  4: 'lg:grid-cols-4',
  5: 'lg:grid-cols-5',
  6: 'lg:grid-cols-6',
  7: 'lg:grid-cols-7',
  8: 'lg:grid-cols-8',
  9: 'lg:grid-cols-9',
  10: 'lg:grid-cols-10',
  11: 'lg:grid-cols-11',
  12: 'lg:grid-cols-12',
};

const xlColsClasses: Record<GridColsNumber, string> = {
  1: 'xl:grid-cols-1',
  2: 'xl:grid-cols-2',
  3: 'xl:grid-cols-3',
  4: 'xl:grid-cols-4',
  5: 'xl:grid-cols-5',
  6: 'xl:grid-cols-6',
  7: 'xl:grid-cols-7',
  8: 'xl:grid-cols-8',
  9: 'xl:grid-cols-9',
  10: 'xl:grid-cols-10',
  11: 'xl:grid-cols-11',
  12: 'xl:grid-cols-12',
};

const gapClasses: Record<GridGap, string> = {
  none: 'gap-0',
  xs: 'gap-2',
  sm: 'gap-3',
  md: 'gap-4',
  lg: 'gap-6',
  xl: 'gap-8',
};

const alignClasses = {
  start: 'items-start',
  center: 'items-center',
  end: 'items-end',
  stretch: 'items-stretch',
  baseline: 'items-baseline',
};

const justifyClasses = {
  start: 'justify-start',
  center: 'justify-center',
  end: 'justify-end',
  between: 'justify-between',
  around: 'justify-around',
  evenly: 'justify-evenly',
};

function resolveColsClasses(cols?: ResponsiveProp<GridColsNumber>): string[] {
  if (cols === undefined) return ['grid-cols-12'];
  if (typeof cols === 'number') {
    return [colsClasses[cols] || 'grid-cols-12'];
  }
  const classes: string[] = [];
  if (cols.base !== undefined) classes.push(colsClasses[cols.base] || '');
  if (cols.sm !== undefined) classes.push(smColsClasses[cols.sm] || '');
  if (cols.md !== undefined) classes.push(mdColsClasses[cols.md] || '');
  if (cols.lg !== undefined) classes.push(lgColsClasses[cols.lg] || '');
  if (cols.xl !== undefined) classes.push(xlColsClasses[cols.xl] || '');
  return classes.filter(Boolean);
}

function resolveGapClass(gap?: ResponsiveProp<GridGap>): string {
  if (!gap) return 'gap-6';
  if (typeof gap === 'string') {
    return gapClasses[gap] || 'gap-6';
  }
  return gapClasses[gap.base || 'lg'] || 'gap-6';
}

export function Grid({
  children,
  className = '',
  cols,
  gap,
  align = 'start',
  justify,
  id,
  style,
  ...props
}: GridProps) {
  const config = useRakitConfig();
  const gridConfig = config?.components?.grid;

  const resolvedCols = cols ?? gridConfig?.defaultCols ?? 12;
  const resolvedGap = gap ?? gridConfig?.defaultGap ?? 'lg';

  const colClasses = resolveColsClasses(resolvedCols);
  const gapClass = resolveGapClass(resolvedGap);
  const alignClass = align ? alignClasses[align] : '';
  const justifyClass = justify ? justifyClasses[justify] : '';
  const identifier = getComponentIdentifier('grid', config, id);

  return (
    <div
      className={cn(
        'grid w-full',
        identifier.className,
        colClasses,
        gapClass,
        alignClass,
        justifyClass,
        gridConfig?.className,
        className
      )}
      data-rakit="grid"
      style={{ ...gridConfig?.style, ...style }}
      {...(identifier.id ? { id: identifier.id } : {})}
      {...props}
    >
      {children}
    </div>
  );
}

// Compound component attachment
Grid.Col = GridCol;
