import { useMemo, useState } from 'react';
import { ArrowDown, ArrowUp, ArrowUpDown, Loader2 } from 'lucide-react';

import { EmptyState } from '../empty-state';
import { Checkbox } from '../field/checkbox/Checkbox';

import { useRakitConfig, getComponentIdentifier } from '../../../config/RakitContext';
import { cn } from '../../../utils/ui/cn';

import type { TableProps, TableRowSelection, TableSize } from '../../../types/ui/table.types';

const sizeHeaderStyles: Record<TableSize, string> = {
  sm: 'py-2.5 px-3.5 text-xs',
  md: 'py-3 px-4 text-xs sm:text-[13px]',
  lg: 'py-3.5 px-4 text-sm',
};

const sizeBodyStyles: Record<TableSize, string> = {
  sm: 'py-2 px-3 text-xs',
  md: 'py-3.5 px-3.5 text-sm',
  lg: 'py-4 px-4 text-sm',
};

export function Table<T>({
  id,
  data,
  columns,
  rowKey,
  emptyTitle = 'Tidak Ada Data',
  emptyMessage = 'No data available',
  emptyIcon,
  emptySlot,
  defaultSortKey,
  defaultSortDirection = 'asc',
  className = '',
  tableClassName = '',
  stickyHeader = true,
  size = 'md',
  isLoading = false,
  loadingMessage = 'Memuat data...',
  loadingSlot,
  skeletonRows = 0,
  rowSelection,
  selectedRowKeys: directSelectedKeys,
  onSelectionChange: directOnSelectionChange,
  onRowClick,
  rowClassName,
  bordered = false,
  striped = false,
}: TableProps<T>) {
  const config = useRakitConfig();
  const identifier = getComponentIdentifier('table', config, id);
  const tableOverride = config.components?.table;

  const [sortKey, setSortKey] = useState<string | null>(defaultSortKey || null);
  const [sortDirection, setSortDirection] = useState<'asc' | 'desc'>(defaultSortDirection);

  // Normalize selection configuration
  const selection: TableRowSelection<T> | undefined = useMemo(() => {
    if (rowSelection) return rowSelection;
    if (directSelectedKeys !== undefined || directOnSelectionChange !== undefined) {
      return {
        selectedRowKeys: directSelectedKeys,
        onChange: directOnSelectionChange,
      };
    }
    return undefined;
  }, [rowSelection, directSelectedKeys, directOnSelectionChange]);

  const handleSort = (columnKey: string, sortable?: boolean) => {
    if (!sortable) return;
    if (sortKey === columnKey) {
      if (sortDirection === 'asc') {
        setSortDirection('desc');
      } else {
        setSortKey(null);
        setSortDirection('asc');
      }
    } else {
      setSortKey(columnKey);
      setSortDirection('asc');
    }
  };

  const getRecordKey = (record: T, index: number): string | number => {
    return rowKey ? rowKey(record, index) : (record as any)?.id ?? index;
  };

  const sortedData = useMemo(() => {
    if (!sortKey) return data;
    const col = columns.find((c) => c.key === sortKey);
    if (!col) return data;

    return [...data].sort((a, b) => {
      let valA: any = col.sortValue ? col.sortValue(a) : (a as any)[sortKey];
      let valB: any = col.sortValue ? col.sortValue(b) : (b as any)[sortKey];

      if (typeof valA === 'string') valA = valA.toLowerCase();
      if (typeof valB === 'string') valB = valB.toLowerCase();

      if (valA === valB) return 0;
      if (valA === null || valA === undefined) return 1;
      if (valB === null || valB === undefined) return -1;

      const compare = valA > valB ? 1 : -1;
      return sortDirection === 'asc' ? compare : -compare;
    });
  }, [data, sortKey, sortDirection, columns]);

  // Row selection calculations
  const selectedKeys = selection?.selectedRowKeys || [];
  const selectableRecords = useMemo(() => {
    if (!selection) return [];
    return sortedData.filter((record) => !selection.getCheckboxProps?.(record)?.disabled);
  }, [selection, sortedData]);

  const isAllSelected = useMemo(() => {
    if (!selection || selectableRecords.length === 0) return false;
    return selectableRecords.every((r, idx) => selectedKeys.includes(getRecordKey(r, idx)));
  }, [selection, selectableRecords, selectedKeys]);

  const isSomeSelected = useMemo(() => {
    if (!selection || selectableRecords.length === 0) return false;
    return (
      !isAllSelected &&
      selectableRecords.some((r, idx) => selectedKeys.includes(getRecordKey(r, idx)))
    );
  }, [selection, selectableRecords, selectedKeys, isAllSelected]);

  const handleSelectAll = (checked: boolean) => {
    if (!selection?.onChange) return;
    if (checked) {
      const allSelectableKeys = selectableRecords.map((r, idx) => getRecordKey(r, idx));
      const combinedKeys = Array.from(new Set([...selectedKeys, ...allSelectableKeys]));
      const selectedRecords = sortedData.filter((r, idx) =>
        combinedKeys.includes(getRecordKey(r, idx))
      );
      selection.onChange(combinedKeys, selectedRecords);
    } else {
      const selectableKeySet = new Set(selectableRecords.map((r, idx) => getRecordKey(r, idx)));
      const remainingKeys = selectedKeys.filter((k) => !selectableKeySet.has(k));
      const selectedRecords = sortedData.filter((r, idx) =>
        remainingKeys.includes(getRecordKey(r, idx))
      );
      selection.onChange(remainingKeys, selectedRecords);
    }
  };

  const handleSelectRow = (record: T, index: number, checked: boolean) => {
    if (!selection?.onChange) return;
    const key = getRecordKey(record, index);
    const newKeys = checked ? [...selectedKeys, key] : selectedKeys.filter((k) => k !== key);
    const selectedRecords = sortedData.filter((r, idx) => newKeys.includes(getRecordKey(r, idx)));
    selection.onChange(newKeys, selectedRecords);
  };

  const totalColSpan = columns.length + (selection ? 1 : 0);
  const checkboxSize = size === 'sm' ? 'xs' : 'sm';

  return (
    <div
      id={identifier.id}
      data-rakit={identifier['data-rakit']}
      className={cn(
        'rakit-table-wrapper w-full overflow-x-auto rounded-2xl border border-slate-200/90 dark:border-slate-800 bg-white dark:bg-slate-900 shadow-2xs',
        identifier.className,
        tableOverride?.className,
        className
      )}
      style={tableOverride?.style}
    >
      <table className={cn('rakit-table w-full text-left border-collapse', tableClassName)}>
        <thead>
          <tr
            className={cn(
              'border-b border-slate-200/90 dark:border-slate-800 font-semibold text-slate-700 dark:text-slate-200 bg-slate-50/90 dark:bg-slate-900/90 backdrop-blur-xs select-none',
              stickyHeader ? 'sticky top-0 z-10' : '',
              sizeHeaderStyles[size]
            )}
          >
            {/* Selection Checkbox Header */}
            {selection && (
              <th
                className={cn(
                  sizeHeaderStyles[size],
                  'w-12 text-center shrink-0 border-r border-slate-200/60 dark:border-slate-800'
                )}
              >
                <div className="flex items-center justify-center">
                  <Checkbox
                    size={checkboxSize}
                    checked={isAllSelected}
                    indeterminate={isSomeSelected}
                    disabled={selectableRecords.length === 0}
                    onChange={handleSelectAll}
                    aria-label="Pilih semua baris"
                  />
                </div>
              </th>
            )}

            {columns.map((col) => {
              const isSorted = sortKey === col.key;
              const stickyClasses =
                col.sticky === 'left'
                  ? 'sticky left-0 z-20 bg-slate-50 dark:bg-slate-900 shadow-[1px_0_0_0_rgb(226,232,240)] dark:shadow-[1px_0_0_0_rgb(30,41,59)]'
                  : col.sticky === 'right'
                  ? 'sticky right-0 z-20 bg-slate-50 dark:bg-slate-900 shadow-[-1px_0_0_0_rgb(226,232,240)] dark:shadow-[-1px_0_0_0_rgb(30,41,59)]'
                  : '';

              return (
                <th
                  key={col.key}
                  style={{ width: col.width }}
                  className={cn(
                    sizeHeaderStyles[size],
                    'transition-colors',
                    stickyClasses,
                    col.sortable ? 'cursor-pointer hover:bg-slate-100/90 dark:hover:bg-slate-800/90' : '',
                    col.headerClassName
                  )}
                  onClick={() => handleSort(col.key, col.sortable)}
                >
                  <div
                    className={cn(
                      'flex items-center gap-1.5',
                      col.align === 'center'
                        ? 'justify-center'
                        : col.align === 'right'
                        ? 'justify-end'
                        : 'justify-start'
                    )}
                  >
                    <span>{col.title}</span>
                    {col.sortable && (
                      <span className="shrink-0 text-slate-400">
                        {isSorted ? (
                          sortDirection === 'asc' ? (
                            <ArrowUp className="w-3.5 h-3.5 text-emerald-600" />
                          ) : (
                            <ArrowDown className="w-3.5 h-3.5 text-emerald-600" />
                          )
                        ) : (
                          <ArrowUpDown className="w-3 h-3 text-slate-300 opacity-60" />
                        )}
                      </span>
                    )}
                  </div>
                </th>
              );
            })}
          </tr>
        </thead>
        <tbody className="divide-y divide-slate-100 dark:divide-slate-800/80 text-slate-700 dark:text-slate-300">
          {isLoading ? (
            loadingSlot ? (
              <tr>
                <td colSpan={totalColSpan}>{loadingSlot}</td>
              </tr>
            ) : skeletonRows > 0 ? (
              Array.from({ length: skeletonRows }).map((_, rIdx) => (
                <tr key={`skeleton-${rIdx}`} className="animate-pulse">
                  {selection && (
                    <td className={cn(sizeBodyStyles[size], 'w-12 text-center')}>
                      <div className="w-4 h-4 mx-auto rounded bg-slate-200/70 dark:bg-slate-700/70" />
                    </td>
                  )}
                  {columns.map((col, cIdx) => {
                    const widthPercent = (60 + ((rIdx + cIdx) * 17) % 35) + '%';
                    return (
                      <td
                        key={`skeleton-cell-${cIdx}`}
                        className={cn(sizeBodyStyles[size], bordered && 'border-r border-slate-100 dark:border-slate-800')}
                      >
                        <div
                          className="h-3.5 rounded-md bg-slate-200/80 dark:bg-slate-700/80"
                          style={{ width: col.width ? '80%' : widthPercent }}
                        />
                      </td>
                    );
                  })}
                </tr>
              ))
            ) : (
              <tr>
                <td colSpan={totalColSpan} className="py-12 px-4 text-center">
                  <div className="flex flex-col items-center justify-center gap-2.5 text-slate-500 dark:text-slate-400">
                    <Loader2 className="w-6 h-6 animate-spin text-emerald-600" />
                    <span className="text-xs font-medium">{loadingMessage}</span>
                  </div>
                </td>
              </tr>
            )
          ) : sortedData.length === 0 ? (
            <tr>
              <td colSpan={totalColSpan} className="py-8 px-4 text-center">
                {emptySlot ? (
                  emptySlot
                ) : (
                  <EmptyState
                    compact={size === 'sm'}
                    className="!border-0 !bg-transparent"
                    icon={emptyIcon}
                    title={emptyTitle}
                    description={emptyMessage}
                  />
                )}
              </td>
            </tr>
          ) : (
            sortedData.map((record, index) => {
              const key = getRecordKey(record, index);
              const isSelected = selectedKeys.includes(key);
              const isClickable = Boolean(onRowClick);
              const checkboxProps = selection?.getCheckboxProps?.(record) || {};
              const customRowClass =
                typeof rowClassName === 'function' ? rowClassName(record, index) : rowClassName;

              return (
                <tr
                  key={key}
                  onClick={() => onRowClick?.(record, index)}
                  className={cn(
                    'transition-colors group',
                    isSelected
                      ? 'bg-emerald-50/60 dark:bg-emerald-950/20'
                      : striped && index % 2 === 1
                      ? 'bg-slate-50/40 dark:bg-slate-800/30'
                      : 'bg-white dark:bg-slate-900',
                    isClickable
                      ? 'cursor-pointer hover:bg-emerald-50/40 dark:hover:bg-emerald-950/30'
                      : !isSelected && 'hover:bg-slate-50/70 dark:hover:bg-slate-800/50',
                    customRowClass
                  )}
                >
                  {/* Selection Row Checkbox */}
                  {selection && (
                    <td
                      className={cn(
                        sizeBodyStyles[size],
                        'w-12 text-center shrink-0 border-r border-slate-100 dark:border-slate-800',
                        isSelected && 'border-emerald-200/60 dark:border-emerald-900/60'
                      )}
                      onClick={(e) => e.stopPropagation()}
                    >
                      <div className="flex items-center justify-center">
                        <Checkbox
                          size={checkboxSize}
                          checked={isSelected}
                          disabled={checkboxProps.disabled}
                          onChange={(checked) => handleSelectRow(record, index, checked)}
                          aria-label={`Pilih baris ${index + 1}`}
                          {...checkboxProps}
                        />
                      </div>
                    </td>
                  )}

                  {columns.map((col) => {
                    const stickyClasses =
                      col.sticky === 'left'
                        ? 'sticky left-0 z-10 bg-white dark:bg-slate-900 group-hover:bg-slate-50/90 dark:group-hover:bg-slate-800/90 shadow-[1px_0_0_0_rgb(241,245,249)] dark:shadow-[1px_0_0_0_rgb(30,41,59)]'
                        : col.sticky === 'right'
                        ? 'sticky right-0 z-10 bg-white dark:bg-slate-900 group-hover:bg-slate-50/90 dark:group-hover:bg-slate-800/90 shadow-[-1px_0_0_0_rgb(241,245,249)] dark:shadow-[-1px_0_0_0_rgb(30,41,59)]'
                        : '';

                    const renderedValue = col.render
                      ? col.render(record, index)
                      : (record as any)[col.key];

                    return (
                      <td
                        key={col.key}
                        className={cn(
                          sizeBodyStyles[size],
                          stickyClasses,
                          col.align === 'center'
                            ? 'text-center'
                            : col.align === 'right'
                            ? 'text-right'
                            : 'text-left',
                          bordered ? 'border-r border-slate-100 dark:border-slate-800 last:border-r-0' : '',
                          col.className
                        )}
                      >
                        {renderedValue}
                      </td>
                    );
                  })}
                </tr>
              );
            })
          )}
        </tbody>
      </table>
    </div>
  );
}

export const DataTable = Table;

// ============================================================================
// TYPES & INTERFACES
// ============================================================================
export type {
  TableProps,
  TableColumn,
  DataTableProps,
  DataTableColumn,
  TableRowSelection,
  TableSize,
  TableAlign,
  TableSticky,
  TableSortDirection,
} from '../../../types/ui/table.types';

