import React from 'react';
import { ParagraphProps, TextSize, TextColor } from '../../../types/ui/typography.types';
import { useRakitConfig, getComponentIdentifier } from '../../../config/RakitContext';

const SIZE_MAP: Record<TextSize, string> = {
  xs: 'text-xs leading-5',
  sm: 'text-sm leading-6',
  md: 'text-base leading-7',
  lg: 'text-lg leading-8',
  xl: 'text-xl leading-9',
};

const COLOR_MAP: Record<TextColor, string> = {
  default: 'text-slate-800 dark:text-slate-200',
  secondary: 'text-slate-600 dark:text-slate-400',
  muted: 'text-slate-500 dark:text-slate-400',
  primary: 'text-emerald-600 dark:text-emerald-400',
  success: 'text-emerald-600 dark:text-emerald-400',
  warning: 'text-amber-600 dark:text-amber-400',
  danger: 'text-rose-600 dark:text-rose-400',
  info: 'text-sky-600 dark:text-sky-400',
  inverse: 'text-white dark:text-slate-950',
};

export const Paragraph: React.FC<ParagraphProps> = ({
  size = 'md',
  color = 'default',
  gutterBottom = true,
  lead = false,
  id,
  className = '',
  children,
  ...props
}) => {
  const config = useRakitConfig();
  const identifier = getComponentIdentifier('paragraph', config, id);

  const classes = [
    'rakit-paragraph',
    identifier.className,
    lead ? 'text-lg md:text-xl font-normal leading-relaxed text-slate-600 dark:text-slate-300' : SIZE_MAP[size],
    lead ? '' : COLOR_MAP[color],
    gutterBottom ? 'mb-4' : 'mb-0',
    className,
  ]
    .filter(Boolean)
    .join(' ');

  return (
    <p
      id={identifier.id}
      data-rakit={identifier['data-rakit']}
      className={classes}
      {...props}
    >
      {children}
    </p>
  );
};
