import { ChevronsLeft, ChevronsRight } from 'lucide-react';
import { cn } from '../../../utils/ui/cn';
import { useSidebar } from './SidebarContext';
import { Button } from '../button';
import type { SidebarToggleProps } from '../../../types/ui/sidebar.types';

export function SidebarToggle({
  collapsed: propCollapsed,
  onToggle: propOnToggle,
  size = 'sm',
  title,
  className = '',
  ...rest
}: SidebarToggleProps) {
  const context = useSidebar();
  const isCollapsed = propCollapsed !== undefined ? propCollapsed : context.collapsed;
  const handleToggle = propOnToggle || context.onToggleCollapse;

  const defaultTitle = isCollapsed ? 'Buka Sidebar' : 'Ciutkan Sidebar';

  const iconSizes = {
    xs: 'w-3 h-3',
    sm: 'w-3.5 h-3.5',
    md: 'w-4 h-4',
  }[size];

  return (
    <Button
      variant="ghost"
      size={size}
      onClick={handleToggle}
      title={title || defaultTitle}
      aria-label={title || defaultTitle}
      className={cn(
        'rakit-sidebar-toggle text-slate-400 hover:text-slate-700 hover:bg-slate-100 dark:text-slate-400 dark:hover:text-slate-200 dark:hover:bg-slate-800 p-1.5',
        className
      )}
      data-rakit="sidebar-toggle"
      data-collapsed={isCollapsed}
      {...(rest as any)}
    >
      {isCollapsed ? (
        <ChevronsRight className={cn(iconSizes, 'shrink-0')} />
      ) : (
        <ChevronsLeft className={cn(iconSizes, 'shrink-0')} />
      )}
    </Button>
  );
}
