import React from 'react';
import { BlockquoteProps } from '../../../types/ui/typography.types';
import { useRakitConfig, getComponentIdentifier } from '../../../config/RakitContext';

export const Blockquote: React.FC<BlockquoteProps> = ({
  cite,
  author,
  color = 'primary',
  id,
  className = '',
  children,
  ...props
}) => {
  const config = useRakitConfig();
  const identifier = getComponentIdentifier('blockquote', config, id);

  const borderColors: Record<string, string> = {
    primary: 'border-emerald-500 bg-emerald-50/40 dark:bg-emerald-950/20 text-slate-800 dark:text-slate-200',
    slate: 'border-slate-400 bg-slate-50 dark:bg-slate-900/40 text-slate-800 dark:text-slate-200',
    amber: 'border-amber-500 bg-amber-50/40 dark:bg-amber-950/20 text-slate-800 dark:text-slate-200',
    rose: 'border-rose-500 bg-rose-50/40 dark:bg-rose-950/20 text-slate-800 dark:text-slate-200',
  };

  const classes = [
    'rakit-blockquote border-l-4 pl-4 py-2.5 my-4 italic rounded-r-lg',
    borderColors[color] || borderColors.primary,
    identifier.className,
    className,
  ]
    .filter(Boolean)
    .join(' ');

  return (
    <blockquote
      id={identifier.id}
      data-rakit={identifier['data-rakit']}
      className={classes}
      cite={cite}
      {...props}
    >
      <div className="not-italic text-base md:text-lg leading-relaxed italic">{children}</div>
      {(author || cite) && (
        <footer className="mt-2 not-italic text-xs font-medium text-slate-500 dark:text-slate-400 flex items-center gap-1.5">
          <span>—</span>
          {author && <span>{author}</span>}
          {cite && <cite className="italic font-normal">({cite})</cite>}
        </footer>
      )}
    </blockquote>
  );
};
