import { cn } from '../../../utils/ui/cn';
import { useSidebar } from './SidebarContext';
import type { SidebarFooterProps } from '../../../types/ui/sidebar.types';

export function SidebarFooter({
  bordered = true,
  className = '',
  children,
  ...rest
}: SidebarFooterProps) {
  const { collapsed } = useSidebar();

  return (
    <div
      className={cn(
        'rakit-sidebar-footer flex flex-col shrink-0 transition-all duration-200 mt-auto',
        bordered && 'border-t border-slate-100 dark:border-slate-800/80',
        collapsed ? 'p-2' : 'p-3',
        className
      )}
      data-rakit="sidebar-footer"
      data-collapsed={collapsed}
      {...rest}
    >
      {children}
    </div>
  );
}
