import React from 'react';
import { Heading } from './Heading';
import { Text } from './Text';
import { Paragraph } from './Paragraph';
import { Kbd } from './Kbd';
import { CodeText } from './CodeText';
import { Blockquote } from './Blockquote';
import { LinkText } from './LinkText';

export interface TypographyComponent extends React.FC<React.HTMLAttributes<HTMLDivElement>> {
  Heading: typeof Heading;
  Text: typeof Text;
  Paragraph: typeof Paragraph;
  Kbd: typeof Kbd;
  Code: typeof CodeText;
  Blockquote: typeof Blockquote;
  Link: typeof LinkText;
}

export const Typography: TypographyComponent = ({
  className = '',
  children,
  ...props
}) => {
  return (
    <div className={`rakit-typography ${className}`} data-rakit="typography" {...props}>
      {children}
    </div>
  );
};

Typography.Heading = Heading;
Typography.Text = Text;
Typography.Paragraph = Paragraph;
Typography.Kbd = Kbd;
Typography.Code = CodeText;
Typography.Blockquote = Blockquote;
Typography.Link = LinkText;
