import type { ReactNode } from 'react';
import { AlertCircle, FileQuestion, Inbox, SearchX, WifiOff } from 'lucide-react';

import { useRakitConfig, getComponentIdentifier } from '../../../config/RakitContext';
import { cn } from '../../../utils/ui/cn';

import type { EmptyStatePreset, EmptyStateProps } from '../../../types/ui/emptyState.types';

const presetDefaults: Record<
  EmptyStatePreset,
  { title: string; description: string; getIcon: (compact: boolean) => ReactNode }
> = {
  '404': {
    title: 'Halaman Tidak Ditemukan',
    description: 'Halaman yang Anda tuju tidak tersedia atau telah dipindahkan.',
    getIcon: (compact) => (
      <div className="relative flex items-center justify-center">
        <div
          className={cn(
            'rounded-2xl bg-slate-100 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 flex items-center justify-center text-slate-500 shadow-2xs',
            compact ? 'w-8 h-8' : 'w-12 h-12'
          )}
        >
          <FileQuestion className={compact ? 'w-4 h-4' : 'w-6 h-6'} />
        </div>
        <span className="absolute -top-1 -right-1 text-[8px] font-bold px-1 py-0.2 rounded-full bg-rose-100 text-rose-700 border border-rose-200">
          404
        </span>
      </div>
    ),
  },
  error: {
    title: 'Terjadi Kesalahan Sistem',
    description: 'Gagal memproses permintaan. Silakan muat ulang atau coba beberapa saat lagi.',
    getIcon: (compact) => (
      <div
        className={cn(
          'rounded-2xl bg-rose-50 dark:bg-rose-950/40 border border-rose-200/80 dark:border-rose-900/60 flex items-center justify-center text-rose-600 dark:text-rose-400 shadow-2xs',
          compact ? 'w-8 h-8' : 'w-12 h-12'
        )}
      >
        <AlertCircle className={compact ? 'w-4 h-4' : 'w-6 h-6'} />
      </div>
    ),
  },
  'no-connection': {
    title: 'Koneksi Terputus',
    description: 'Tidak dapat terhubung ke server. Periksa jaringan internet atau firewall Anda.',
    getIcon: (compact) => (
      <div
        className={cn(
          'rounded-2xl bg-amber-50 dark:bg-amber-950/40 border border-amber-200/80 dark:border-amber-900/60 flex items-center justify-center text-amber-600 dark:text-amber-400 shadow-2xs',
          compact ? 'w-8 h-8' : 'w-12 h-12'
        )}
      >
        <WifiOff className={compact ? 'w-4 h-4' : 'w-6 h-6'} />
      </div>
    ),
  },
  search: {
    title: 'Hasil Pencarian Nihil',
    description: 'Tidak ditemukan data yang cocok dengan kriteria kata kunci pencarian Anda.',
    getIcon: (compact) => (
      <div
        className={cn(
          'rounded-2xl bg-slate-100 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 flex items-center justify-center text-slate-500 shadow-2xs',
          compact ? 'w-8 h-8' : 'w-12 h-12'
        )}
      >
        <SearchX className={compact ? 'w-4 h-4' : 'w-6 h-6'} />
      </div>
    ),
  },
  empty: {
    title: 'Belum Ada Data',
    description: 'Data belum tersedia atau belum ada item yang dibuat pada segmen ini.',
    getIcon: (compact) => (
      <div
        className={cn(
          'rounded-2xl bg-emerald-50/70 dark:bg-emerald-950/30 border border-emerald-200/70 dark:border-emerald-900/50 flex items-center justify-center text-emerald-600 dark:text-emerald-400 shadow-2xs',
          compact ? 'w-8 h-8' : 'w-12 h-12'
        )}
      >
        <Inbox className={compact ? 'w-4 h-4' : 'w-6 h-6'} />
      </div>
    ),
  },
};

export function EmptyState({
  id,
  preset,
  icon,
  title,
  description,
  action,
  compact = false,
  theme = 'light',
  className = '',
}: EmptyStateProps) {
  const config = useRakitConfig();
  const identifier = getComponentIdentifier('empty-state', config, id);
  const emptyStateOverride = config.components?.emptyState;
  const isDark = theme === 'dark';

  const presetInfo = preset ? presetDefaults[preset] : undefined;
  const resolvedTitle = title ?? presetInfo?.title ?? 'Tidak Ada Data';
  const resolvedDescription = description ?? presetInfo?.description;
  const resolvedIcon = icon ?? (presetInfo ? presetInfo.getIcon(compact) : undefined);

  return (
    <div
      id={identifier.id}
      data-rakit={identifier['data-rakit']}
      className={cn(
        'rakit-empty-state flex flex-col items-center justify-center text-center rounded-xl select-none transition-colors',
        isDark ? 'bg-slate-950/60 text-slate-300' : 'bg-slate-50/40 text-slate-700',
        compact ? 'p-4 sm:p-5 gap-2' : 'p-8 sm:p-12 gap-3',
        identifier.className,
        emptyStateOverride?.className,
        className
      )}
      style={emptyStateOverride?.style}
    >
      {resolvedIcon && (
        <div className="shrink-0">
          {presetInfo && !icon ? (
            resolvedIcon
          ) : (
            <div
              className={cn(
                'rounded-xl shadow-2xs flex items-center justify-center shrink-0',
                isDark
                  ? 'bg-slate-900 border border-slate-800 text-slate-400'
                  : 'bg-white border border-slate-200/70 text-slate-400',
                compact ? 'w-8 h-8' : 'w-11 h-11'
              )}
            >
              {resolvedIcon}
            </div>
          )}
        </div>
      )}
      <div className="max-w-xs space-y-0.5">
        <h4
          className={cn(
            'text-xs sm:text-sm font-semibold tracking-tight leading-snug',
            isDark ? 'text-slate-200' : 'text-slate-700'
          )}
        >
          {resolvedTitle}
        </h4>
        {resolvedDescription && (
          <p
            className={cn(
              'text-[11px] sm:text-xs leading-relaxed',
              isDark ? 'text-slate-400' : 'text-slate-500'
            )}
          >
            {resolvedDescription}
          </p>
        )}
      </div>
      {action && <div className="mt-1">{action}</div>}
    </div>
  );
}

// ============================================================================
// TYPES & INTERFACES
// ============================================================================
export type { EmptyStateProps, EmptyStatePreset } from '../../../types/ui/emptyState.types';

