import React from 'react';
import { CodeTextProps } from '../../../types/ui/typography.types';
import { useRakitConfig, getComponentIdentifier } from '../../../config/RakitContext';

export const CodeText: React.FC<CodeTextProps> = ({
  id,
  className = '',
  children,
  ...props
}) => {
  const config = useRakitConfig();
  const identifier = getComponentIdentifier('code', config, id);

  const classes = [
    'rakit-code font-mono text-xs md:text-sm px-1.5 py-0.5 rounded-md',
    'bg-slate-100 text-emerald-700 border border-slate-200/80',
    'dark:bg-slate-800/80 dark:text-emerald-400 dark:border-slate-700/80',
    identifier.className,
    className,
  ]
    .filter(Boolean)
    .join(' ');

  return (
    <code
      id={identifier.id}
      data-rakit={identifier['data-rakit']}
      className={classes}
      {...props}
    >
      {children}
    </code>
  );
};
